+        };
+        assert_eq!(
+            setup.encode().unwrap_err(),
+            SetupError::CutoffEndpoints,
+            "{entry:?} {exit:?}"
+        );
+    }
+    for mm in [15, 40, 80] {
+        let setup = CutoffSetup20 {
+            height_um: mm * 1000,
+            ..lower()
+        };
+        assert_eq!(
+            setup.encode().unwrap_err(),
+            SetupError::UnqualifiedCutoffHeight
+        );
+    }
+    let bad = CutoffSetup20 {
+        stem: "lower",
+        ..lower()
+    };
+    assert_eq!(bad.encode().unwrap_err(), SetupError::InvalidStem);
+}

