+#[test]
+fn a_die_group_refuses_other_heights_counts_and_repeated_stems() {
+    // Three distinct openings: the control checked die groups of two only.
+    let third = GroupPunch {
+        iso_stem: "DUODI203",
+        ..OPENINGS[1]
