+            },
+            SetupError::UnqualifiedGroupHeight,
+        ),
+    ] {
+        assert_eq!(group.encode_die().unwrap_err(), expected);
+    }
+    let outside = [
+        OPENINGS[0],
+        GroupPunch {
+            iso_stem: "DUODI202",
+            start_hole_um: [64_500, 0],
+        },
