+            "  ok=JE_GenerateCuts(WORK,je_piece,\"PAIR20\",\"CUT1\",ASDELETE,NULL)",
+            "  ok=JE_GenerateCuts(WORK,je_piece,\"PAIR20\",\"CUT2\",ASDELETE,NULL)",
+        ]
+    );
+    assert!(files.controller_review.contains("245, 155, 140 and 134 µm"));
+    assert!(
+        files
