+#[test]
+fn a_group_refuses_its_unqualified_inputs() {
+    // Ten distinct stems: one work above the largest control-checked group.
+    let ten: Vec<_> = TEN_STEMS
+        .iter()
+        .zip(-5..)
+        .map(|(iso_stem, i)| GroupPunch {
+            iso_stem,
