+        ),
+        (
+            PunchGroup20 {
+                height_um: 15_000,
+                ..pair(&PUNCHES)
+            },
+            SetupError::UnqualifiedGroupHeight,
+        ),
+        (
+            PunchGroup20 {
+                stock_max_um: [400_000, 30_000],
+                ..pair(&PUNCHES)
+            },
+            SetupError::InvalidStock,
+        ),
+    ] {
+        assert_eq!(setup.encode().unwrap_err(), expected, "{setup:?}");
+    }
+}

